import {ReactElement, ReactNode} from "react";
import {ToolSchema, UserConfigSchema} from "../../../../types/tool.types";

export type RenderConfigProps = {
    userConfig: Record<string, any>;
    onConfigChange: (key: string, value: string | number | boolean) => void;
};

/**
 * Unique identifier for one run-trigger, generated by LlmProcessNode that orchestrates a tool call
 * and is forwarded to every connected tool. Lets a tool scope
 * per-run resources it opens (e.g. FormInteractionTool's browser session) so two concurrent
 * runs of the same workflow (e.g. launched from two tabs) don't collide.
 */
export type SessionId = string;

export type ToolDefinition = {
    toolSubtype: string;
    title: string;
    icon: ReactElement<{className?: string; color?: string}>;
    toolSchema: ToolSchema;
    userConfigSchema: UserConfigSchema;
    handlerFactory: (userConfig: any) => (params: any) => Promise<any>;
    /**
     * Dot paths into the tool node's data (e.g. `userConfig.apiKey`) that are deleted when the workflow is saved, so
     * secrets such as API keys and access tokens never reach a workflow file. They're added to the generic ToolNode's
     * own list when this tool is picked. Empty when the tool holds no secrets.
     */
    toSanitize: string[];
    /**
     * The global store keys this tool's secrets are shared under (e.g. `brave-search.apiKey`): every tool node of
     * the kind shows and runs with the same value, and Settings → Credentials offers to save it. Session-only
     * values, like the Google access tokens, aren't listed. Optional; most tools have none.
     */
    globalSecrets?: readonly string[];
    renderConfig?: (props: RenderConfigProps) => ReactNode;
    /**
     * Optional per-tool cleanup, bound to userConfig at config-time like handlerFactory.
     * Invoked once by LlmProcessNode after a run ends (success or failure), passing only
     * that run's sessionId — lets a tool release resources it may have opened during the
     * run (e.g. a browser session) without LlmProcessNode knowing anything tool-specific.
     */
    runtimeCleanup?: (userConfig: any) => (sessionId: SessionId) => Promise<void>;
};